"""Standalone browser explorer, served by Jupyter or python -m http.server; no external services."""
import json
from pathlib import Path

def write_viewer(output,reports,standalone=False):
    directory=Path(output);features=[{'id':r['feature'],'size':r['size'],'locations':r['locations'],'dungeons':r['dungeons']}for r in reports]
    html='''<!doctype html><html lang="pl"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>KI Legends — Superior</title><style>body{margin:0;background:#102a36;color:#e5ede3;font:16px system-ui}header,aside{padding:16px}main{display:grid;grid-template-columns:280px 1fr}button,select{padding:10px;background:#244754;color:#f4e8c1;border:1px solid #789386;margin:4px;cursor:pointer}canvas{max-width:100%;background:#143449;touch-action:manipulation}#map{position:relative}#map img{width:100%;display:block}#overlay{background:transparent;position:absolute;inset:0;width:100%;height:100%}#viewport{overflow:auto;max-height:85vh}a{color:#e8cc94}#maze{image-rendering:pixelated}pre{white-space:pre-wrap}label{display:block;padding:6px}@media(max-width:800px){main{display:block}}</style><header><h1>Superior — wygenerowany świat</h1><p>Geometria planety z repozytorium. Dane do integracji z grą; podgląd schematyczny.</p><a href="viewer.html">Samodzielny podgląd (Jupyter)</a> · <a href="generation-report.json">Raport generacji</a> · <a href="spawn-report.json">Osobny raport spawnów</a></header><main><aside><select id="regions"></select><p id="facts"></p><label><input id="secrets" type="checkbox">Pokaż ukryte lokacje</label><label><input id="spawns" type="checkbox">Pokaż osobno wygenerowane spawny</label><label>Powiększenie <input id="zoom" type="range" min="1" max="6" value="1" step="0.25"></label><select id="locations"></select><pre id="details"></pre><p><a id="download">Dane krainy</a></p><h2>Wnętrze / labirynt</h2><canvas id="maze"></canvas><label><input id="solve" type="checkbox">Pokaż rozwiązanie</label><p>Wejście: zielone. Wyjście: złote. Czerwone punkty: spawny we wnętrzu.</p></aside><section><div id="viewport"><div id="map"><img id="terrain" alt="Teren i drogi krainy"><canvas id="overlay"></canvas></div></div><p id="selected"></p></section></main><script>
const embedded=EMBEDDED;const getData=async path=>{if(embedded){if(!(path in embedded))throw Error('Brak danych: '+path);return embedded[path]}const r=await fetch(path);if(!r.ok)throw Error('HTTP '+r.status);return await r.json()};const features=FEATURES;let world=null,spawnData=null,dungeon=null;const el=id=>document.getElementById(id);features.sort((a,b)=>a.id.localeCompare(b.id));for(const f of features)el('regions').add(new Option(f.id,f.id));
async function load(){const id=el('regions').value;world=await getData(id+'/world.json');spawnData=null;try{spawnData=await getData('spawns/'+id+'/spawns.json')}catch{};el('terrain').src=embedded?embedded[id+'/minimap.png']:id+'/minimap.png';el('download').href=id+'/world.json';el('facts').textContent=world.name+' · '+world.geometry.width+' × '+world.geometry.height+' · '+world.locations.length+' miejsc · '+world.dungeons.length+' wnętrz';el('locations').replaceChildren();for(const p of world.locations.filter(p=>!p.hidden||el('secrets').checked))el('locations').add(new Option(p.id+' ('+p.kind+')',p.id));draw();selectLocation()}
function draw(){if(!world)return;const c=el('overlay');c.width=1800;c.height=Math.round(1800*world.geometry.height/world.geometry.width);const ctx=c.getContext('2d'),sx=c.width/world.geometry.width,sy=c.height/world.geometry.height;ctx.clearRect(0,0,c.width,c.height);ctx.fillStyle='#d6c399';for(const b of world.buildings){const r=b.footprint;if(r)ctx.fillRect(r.x*sx,r.y*sy,r.width*sx,r.height*sy)}for(const p of world.locations){if(p.hidden&&!el('secrets').checked)continue;ctx.fillStyle=p.hidden?'#ef9bf2':'#fff1ad';ctx.beginPath();ctx.arc(p.x*sx,p.y*sy,p.kind==='settlement'?7:4,0,7);ctx.fill()}if(el('spawns').checked&&spawnData){ctx.fillStyle='#ff6c65';for(const p of spawnData.overworld){ctx.beginPath();ctx.arc(p.x*sx,p.y*sy,2,0,7);ctx.fill()}}}
function selectLocation(){if(!world)return;const p=world.locations.find(p=>p.id===el('locations').value);el('details').textContent=JSON.stringify(p,null,2);dungeon=world.dungeons.find(d=>d.id===p?.id);drawMaze()}
function drawMaze(){const c=el('maze');if(!dungeon){c.width=1;c.height=1;return}const n=dungeon.floor.length,t=8;c.width=n*t;c.height=n*t;const ctx=c.getContext('2d');ctx.fillStyle='#17232b';ctx.fillRect(0,0,c.width,c.height);ctx.fillStyle='#b6b797';dungeon.floor.forEach((row,y)=>[...row].forEach((v,x)=>{if(v==='1')ctx.fillRect(x*t,y*t,t,t)}));const mark=(p,color)=>{ctx.fillStyle=color;ctx.fillRect(p.x/dungeon.cellSize*t-3,p.y/dungeon.cellSize*t-3,6,6)};if(el('solve').checked){ctx.strokeStyle='#a976d9';ctx.lineWidth=2;ctx.beginPath();dungeon.solution.forEach(([x,y],i)=>{if(i)ctx.lineTo(x/dungeon.cellSize*t,y/dungeon.cellSize*t);else ctx.moveTo(x/dungeon.cellSize*t,y/dungeon.cellSize*t)});ctx.stroke()}mark(dungeon.entrance,'#20e187');mark(dungeon.exit,'#ffd65b');if(el('spawns').checked&&spawnData){for(const p of spawnData.interiors.filter(p=>p.dungeon===dungeon.id))mark(p,'#d84943')}}
el('zoom').oninput=()=>{el('map').style.width=(Number(el('zoom').value)*100)+'%'};el('regions').onchange=load;el('locations').onchange=selectLocation;el('secrets').onchange=load;el('spawns').onchange=()=>{draw();drawMaze()};el('solve').onchange=drawMaze;el('overlay').onclick=e=>{if(!world)return;const r=e.target.getBoundingClientRect(),x=(e.clientX-r.left)/r.width*world.geometry.width,y=(e.clientY-r.top)/r.height*world.geometry.height;const p=world.locations.filter(p=>!p.hidden||el('secrets').checked).sort((a,b)=>Math.hypot(a.x-x,a.y-y)-Math.hypot(b.x-x,b.y-y))[0];if(p){el('locations').value=p.id;selectLocation()}};el('terrain').onload=draw;load().catch(e=>el('facts').textContent=e.message);
</script></html>'''
    embedded=None
    if standalone:
        import base64
        embedded={}
        for f in features:
            fid=f['id']
            embedded[fid+'/world.json']=json.loads((directory/fid/'world.json').read_text())
            embedded[fid+'/minimap.png']='data:image/png;base64,'+base64.b64encode((directory/fid/'minimap.png').read_bytes()).decode()
            path=directory/'spawns'/fid/'spawns.json'
            if path.exists():embedded['spawns/'+fid+'/spawns.json']=json.loads(path.read_text())
    payload=json.dumps(embedded,ensure_ascii=False).replace('<','\\u003c')
    (directory/('viewer.html' if standalone else 'index.html')).write_text(html.replace('FEATURES',json.dumps(features)).replace('EMBEDDED',payload),encoding='utf8')

if __name__=='__main__':
    import argparse
    p=argparse.ArgumentParser(description='Build a single-file explorer that also works in Jupyter sandbox.')
    p.add_argument('--world',required=True);a=p.parse_args()
    write_viewer(a.world,json.loads((Path(a.world)/'generation-report.json').read_text())['features'],standalone=True)
